package com.scriptles.cabinet.profile.repository;
import com.scriptles.cabinet.profile.entity.Profile; import com.scriptles.cabinet.profile.enums.ProfileType; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.Optional; import java.util.UUID;
public interface ProfileRepository extends JpaRepository<Profile,UUID> { Optional<Profile> findByHandleIgnoreCase(String handle); Optional<Profile> findByUserId(UUID userId); boolean existsByHandleIgnoreCase(String handle); @Query("select p from Profile p where p.active=true and (lower(p.handle) like lower(concat('%',:q,'%')) or lower(p.displayName) like lower(concat('%',:q,'%'))) order by p.verified desc, lower(p.displayName)") Page<Profile> search(@Param("q") String q, Pageable pageable); @Query("select p from Profile p where p.active=true and p.type=:type and (lower(p.handle) like lower(concat('%',:q,'%')) or lower(p.displayName) like lower(concat('%',:q,'%'))) order by p.verified desc, lower(p.displayName)") Page<Profile> searchByType(@Param("q") String q, @Param("type") ProfileType type, Pageable pageable); Page<Profile> findByType(ProfileType type, Pageable pageable); }
